package com.echovault.servlet;
import com.echovault.dao.CapsuleDAO;import com.echovault.util.Flash;import jakarta.servlet.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.*;
@WebServlet("/dashboard") public class DashboardServlet extends HttpServlet{protected void doGet(HttpServletRequest q,HttpServletResponse s)throws ServletException,IOException{HttpSession h=q.getSession(false);if(h==null||h.getAttribute("userId")==null){s.sendRedirect("login.jsp");return;}try{CapsuleDAO d=new CapsuleDAO();q.setAttribute("capsules",d.listForUser((Integer)h.getAttribute("userId"),(String)h.getAttribute("userEmail")));q.setAttribute("capsuleCount",d.countForUser((Integer)h.getAttribute("userId")));q.getRequestDispatcher("dashboard.jsp").forward(q,s);}catch(Exception e){throw new ServletException(e);}}}